LINE_RE = re.compile(r'^(?P<speaker>[^:]+):\s*(?P<text>.*?)\s*->\s*(?P<target>\S+)\s*$')
CHOICE_RE = re.compile(r'^\d+\.\s*(?P<text>.*?)\s*->\s*(?P<target>\S+)\s*$')


def parse_script(text: str):
    lines = text.splitlines()

    # Group lines into sections keyed by header id, preserving declaration order.
    sections = []  # list of (id, [content_lines])
    current_id = None
    current_body = []
    for raw in lines:
        line = raw.rstrip()
        if not line.strip():
            continue
        m = SECTION_RE.match(line.strip())
        if m:
            if current_id is not None:
                sections.append((current_id, current_body))
            current_id = m.group(1).strip()
            current_body = []
        else:
            if current_id is not None:
                current_body.append(line.strip())
    if current_id is not None:
        sections.append((current_id, current_body))

    nodes = []
    edges = []
    declared_ids = set()

    for sec_id, body in sections:
        declared_ids.add(sec_id)
        if not body:
            nodes.append({"id": sec_id, "text": "", "speaker": "", "type": "line"})
            continue

        is_choice = all(re.match(r'^\d+\.', b) for b in body)

        if is_choice:
            nodes.append({"id": sec_id, "text": "", "speaker": "", "type": "choice"})
            for opt in body:
                cm = CHOICE_RE.match(opt)
                if not cm:
                    raise ValueError(f"Malformed choice line in [{sec_id}]: {opt!r}")
                edges.append({
                    "from": sec_id,
                    "to": cm.group("target").strip(),
                    "text": cm.group("text").strip(),
                })
        else:
            if len(body) != 1:
                raise ValueError(f"Expected single line in [{sec_id}], got {body!r}")
            lm = LINE_RE.match(body[0])
            if not lm:
                raise ValueError(f"Malformed line in [{sec_id}]: {body[0]!r}")
            nodes.append({
                "id": sec_id,
                "text": lm.group("text").strip(),
                "speaker": lm.group("speaker").strip(),
                "type": "line",
            })
            edges.append({
                "from": sec_id,
                "to": lm.group("target").strip(),
                "text": "",
            })

    # Materialize referenced-but-undefined targets as implicit line nodes.
    referenced = {e["to"] for e in edges}
    for ref in referenced:
        if ref not in declared_ids:
            nodes.append({"id": ref, "text": "", "speaker": "", "type": "line"})
            declared_ids.add(ref)

