    out = ["digraph Dialogue {"]
    for n in graph["nodes"]:
        label = f'{n["id"]}'
        if n["speaker"]:
            label += f'\\n{n["speaker"]}: {n["text"]}'
        elif n["text"]:
            label += f'\\n{n["text"]}'
        shape = "box" if n["type"] == "line" else "diamond"
        out.append(f'  "{_dot_escape(n["id"])}" [label="{_dot_escape(label)}", shape={shape}];')
